insert into public.flavors (slug, name, name_kana, description, notes, assort_only) values
  ('plain', '豆乳サンドビスケット', 'とうにゅうさんどびすけっと', '豆乳入りビスケットで豆乳クリームをサンドした定番品（個包装）。', '通年の定番。公式オンラインストアの現行表記は「豆乳サンドビスケット 10p」。', false),
